import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent

def add_abstain(w):
    d=json.loads((ROOT/'results.json').read_text(encoding='utf8'))['methods']
    w.page('Когда читать   /   258 задач вне Lite','Когда можно пропустить доставку памяти',
           'В открытой библиотеке у 185 из 258 запросов нашлась хотя бы одна история из того же репозитория, влитая к моменту нового запроса. Всегда показывая первую карточку, агент получил бы 26 размеченных связей. Мы зафиксировали эту первую карточку и меняли только решение о её показе.')
    w.p('Проверяемое правило требует общий идентификатор в поле исторической правки или хотя бы два разных общих идентификатора в предыдущем описании. Учитываются имена файлов, квалифицированные имена, snake_case и смешанный регистр. Из текста заранее убраны URL и номера задач. Для сравнений с фиксированным бюджетом память выбирали по абсолютному BM25, его отрыву от второй карточки либо взвешенному совпадению идентификаторов.')
    data=[]
    for k,t in [('all','Показывать всегда'),('gate','Правило по идентификаторам'),('bm25_25','BM25 · бюджет 25%'),('margin_25','Отрыв BM25 · 25%'),('symbol_25','Идентификаторы · 25%'),('bm25_50','BM25 · 50%'),('margin_50','Отрыв BM25 · 50%'),('symbol_50','Идентификаторы · 50%')]:
        r=d[k];data.append([t,str(r['deliveries']),str(r['linked_delivered']),f"{r['precision']*100:.1f} %",f"{r['matched_random_expected']:.1f}"])
    w.tbl(['Способ чтения','Показов','Связей','Точность','Случайно¹'],data,[6.1,2.5,2.1,3.1,3.3],True)
    w.p('¹ Математическое ожидание для случайной доставки с тем же числом карточек внутри каждого репозитория. Правило по идентификаторам сэкономило 130 из 185 показов и потеряло 12 из 26 связей. При бюджете 75% все способы сделали 139 показов и сохранили соответственно 23, 24 и 23 связи. По этим данным более сложное условие не получило преимущества перед отрывом BM25.','Caption')
    w.p('Бюджетные кривые ретроспективны: порог для нужного процента устанавливается по неразмеченным оценкам всего набора. Фиксированное правило можно применять сразу. Полная разметка полезности всех карточек и тесты исправлений для этой проверки отсутствуют. Число показов измеряет обращения к памяти; длина контекста разных карточек различается.')

